#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>

#define BUFFER_SIZE 4096
#define MAX_SESSIONS 64

typedef struct {
    char *request_buf;
    char *response_buf;
    int active;
    int sock_fd;
} session_t;

session_t sessions[MAX_SESSIONS];
pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

void cleanup_session(int idx) {
    pthread_mutex_lock(&session_lock);
    if (sessions[idx].request_buf) {
        free(sessions[idx].request_buf);
        sessions[idx].request_buf = NULL;
    }
    if (sessions[idx].response_buf) {
        free(sessions[idx].response_buf);
        sessions[idx].response_buf = NULL;
    }
    sessions[idx].active = 0;
    pthread_mutex_unlock(&session_lock);
}

void handle_timeout(int idx) {
    /* Race condition: timeout handler doesn't check if already freed */
    if (sessions[idx].active) {
        free(sessions[idx].request_buf);
        free(sessions[idx].response_buf);
        sessions[idx].active = 0;
        close(sessions[idx].sock_fd);
    }
}

void *timeout_monitor(void *arg) {
    while (1) {
        sleep(30);
        for (int i = 0; i < MAX_SESSIONS; i++) {
            if (sessions[i].active) {
                handle_timeout(i);
            }
        }
    }
    return NULL;
}

void *handle_connection(void *arg) {
    int idx = *(int *)arg;
    free(arg);

    sessions[idx].request_buf = (char *)malloc(BUFFER_SIZE);
    sessions[idx].response_buf = (char *)malloc(BUFFER_SIZE);
    sessions[idx].active = 1;

    int bytes = recv(sessions[idx].sock_fd, sessions[idx].request_buf, BUFFER_SIZE - 1, 0);
    if (bytes <= 0) {
        cleanup_session(idx);
        return NULL;
    }
    sessions[idx].request_buf[bytes] = '\0';

    /* Process request - build response */
    snprintf(sessions[idx].response_buf, BUFFER_SIZE,
             "HTTP/1.0 200 OK\r\nContent-Length: %d\r\n\r\n%s",
             bytes, sessions[idx].request_buf);

    send(sessions[idx].sock_fd, sessions[idx].response_buf,
         strlen(sessions[idx].response_buf), 0);

    /* Double-free vulnerability: cleanup_session frees buffers,
       but timeout_monitor may also free them due to race condition
       between active check and free in handle_timeout (no lock held) */
    cleanup_session(idx);
    close(sessions[idx].sock_fd);
    return NULL;
}

int main(int argc, char *argv[]) {
    int server_fd;
    struct sockaddr_in addr;
    pthread_t tid;

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(8080);

    bind(server_fd, (struct sockaddr *)&addr, sizeof(addr));
    listen(server_fd, 128);

    pthread_create(&tid, NULL, timeout_monitor, NULL);

    int session_idx = 0;
    while (1) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) continue;

        int *idx = malloc(sizeof(int));
        *idx = session_idx % MAX_SESSIONS;
        sessions[*idx].sock_fd = client_fd;

        pthread_t conn_tid;
        pthread_create(&conn_tid, NULL, handle_connection, idx);
        pthread_detach(conn_tid);
        session_idx++;
    }
    return 0;
}
